/**
 * Load a price-book dump into the app's SQLite.
 *
 * The dump is produced by `tools/price-dump` and is trusted — it is generated by
 * us from the client's own database. It is still treated with care: table and
 * column names must be plain identifiers, because they become part of a `CREATE
 * TABLE` statement and SQL does not allow binding an identifier.
 *
 * Each table is dropped and recreated inside its own transaction, so a failure
 * half way through leaves the tables already loaded intact and the rest
 * untouched, rather than a database that is neither the old one nor the new one.
 */

import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import type { DatabaseSync } from 'node:sqlite';
import { PRICE_META_KEYS } from './schema';

export interface ImportReport {
  tables: { name: string; rows: number }[];
  importedAt: number;
  sourceFile: string;
  sourceHash: string;
  /** Objects whose name was not a plain identifier, and were therefore not created. */
  skipped: string[];
  /**
   * Columns whose name was not a legal identifier and were renamed, as
   * `table.source→column`.
   *
   * Reported rather than silent, because a renamed column is a column a query has
   * to know the new name of. The real book has one: `system_lookup_data.no_M/EW`.
   */
  renamed: string[];
}

/** A name that can safely become part of a `CREATE TABLE` statement. */
const SAFE_IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;

/**
 * A column name the dump can legally carry, made into a legal identifier.
 *
 * The dump is somebody else's database, and one of its real columns is
 * `no_M/EW` — a slash, which no bare SQL identifier may contain. The importer
 * used to **skip the whole table** when it met such a column, which silently
 * dropped `system_lookup_data` (2 752 rows naming the frame section for every
 * span, bay, height and wind code) out of every published book. The engine then
 * had no structure-to-section table, priced every member as one fixed SHS, and
 * nothing failed loudly enough for anyone to notice.
 *
 * So the name is rewritten instead of the table dropped. The rewrite is a pure
 * function of the original name, which is what lets a query find the column
 * again: `columnFor('no_M/EW')` is `'no_M_EW'` at import time and at read time.
 *
 * The rules, in order:
 *  - every character outside `[A-Za-z0-9_]` becomes `_`, so `no_M/EW` → `no_M_EW`;
 *  - a leading digit gains a leading `_`, because an identifier may not start
 *    with one;
 *  - an empty name becomes `_`.
 */
export function columnFor(name: string): string {
  const replaced = name.replace(/[^A-Za-z0-9_]/g, '_');
  if (replaced === '') return '_';
  return /^[0-9]/.test(replaced) ? `_${replaced}` : replaced;
}

/**
 * Give every column a legal name, keeping them distinct.
 *
 * Two source columns could sanitise to one name (`a/b` and `a.b` both become
 * `a_b`). A collision would make `CREATE TABLE` fail, so the later one gets a
 * numeric suffix — deterministically, from its position, so a re-import produces
 * the same schema.
 */
function columnNames(columns: string[]): { source: string; column: string }[] {
  const taken = new Set<string>();
  return columns.map((source) => {
    const base = columnFor(source);
    let column = base;
    let suffix = 2;
    while (taken.has(column)) {
      column = `${base}_${suffix}`;
      suffix += 1;
    }
    taken.add(column);
    return { source, column };
  });
}

/**
 * Tables the importer owns. A dump must not replace them: `price_book_meta`
 * records the publication's own provenance, and a dump that overwrote it would
 * destroy the answer to "which book priced this quote".
 */
const RESERVED_TABLES = new Set(['price_book_meta', 'sqlite_sequence']);

/**
 * A quoted identifier, with any embedded quote doubled.
 *
 * The dump is a JSON file, and its keys become column names. Doubling the quote
 * is what makes a `"` in a key a literal character instead of the end of the
 * identifier — without it a key such as `x" TEXT); DROP TABLE price_book_meta; --`
 * closes the identifier and runs as SQL. Callers also reject anything that is not
 * a plain identifier, so this is the second of two guards rather than the only
 * one.
 */
function quote(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/** `INTEGER` when every non-null value is an integer, `REAL` when numeric, else `TEXT`. */
function columnType(values: unknown[]): 'INTEGER' | 'REAL' | 'TEXT' {
  const present = values.filter((value) => value !== null && value !== undefined);
  if (present.length === 0) return 'TEXT';
  if (present.every((value) => typeof value === 'number' && Number.isInteger(value))) {
    return 'INTEGER';
  }
  if (present.every((value) => typeof value === 'number')) return 'REAL';
  return 'TEXT';
}

/** The column names of a table, in first-seen order across all its rows. */
function columnsOf(rows: Record<string, unknown>[]): string[] {
  const seen: string[] = [];
  const known = new Set<string>();
  for (const row of rows) {
    for (const key of Object.keys(row)) {
      if (!known.has(key)) {
        known.add(key);
        seen.push(key);
      }
    }
  }
  return seen;
}

/** The table names to import: the summary's, or every `.json` when it is absent. */
function tableNames(dir: string): string[] {
  const summaryPath = join(dir, '_summary.tsv');
  try {
    const lines = readFileSync(summaryPath, 'utf8').split('\n');
    const names: string[] = [];
    for (const line of lines) {
      if (line.trim() === '') continue;
      const [name, , count] = line.split('\t');
      if (name !== undefined && count !== undefined && !count.startsWith('ERROR')) {
        names.push(name);
      }
    }
    if (names.length > 0) return names;
  } catch {
    // No summary: fall through to the directory listing.
  }
  return readdirSync(dir)
    .filter((file) => file.endsWith('.json'))
    .map((file) => file.slice(0, -'.json'.length))
    .sort();
}

/**
 * Whether a dump is the sample book or a licensed one.
 *
 * `'sample'` only when the dump says so in its own `BOOK_KIND.json`. Everything
 * else is `'licensed'`, and that default is deliberate: the flag decides whether
 * a stranger may see a price list, so an unmarked dump must be treated as the
 * real thing. Guessing `'sample'` from a directory name is how a licensed book
 * would end up on a public demo.
 */
export function readBookKind(dir: string): 'sample' | 'licensed' {
  const marker = join(dir, 'BOOK_KIND.json');
  if (!existsSync(marker)) return 'licensed';
  try {
    const parsed = JSON.parse(readFileSync(marker, 'utf8')) as { kind?: unknown };
    return parsed.kind === 'sample' ? 'sample' : 'licensed';
  } catch {
    return 'licensed';
  }
}

/**
 * Import every table in `dir` into `db`, replacing what was there.
 *
 * The hash is over each file's name, row count, and byte length rather than its
 * contents: 31 000 rows of suburb data do not need to be hashed to answer "is
 * this the same dump", and the byte length catches an edited file.
 */
export function importPriceBook(db: DatabaseSync, dir: string): ImportReport {
  const names = tableNames(dir);
  const tables: { name: string; rows: number }[] = [];
  const skipped: string[] = [];
  const renamed: string[] = [];
  const hashParts: string[] = [];

  for (const name of names) {
    if (!SAFE_IDENTIFIER.test(name) || RESERVED_TABLES.has(name)) {
      skipped.push(name);
      continue;
    }

    const file = join(dir, `${name}.json`);
    let rows: Record<string, unknown>[];
    try {
      rows = JSON.parse(readFileSync(file, 'utf8')) as Record<string, unknown>[];
    } catch {
      skipped.push(name);
      continue;
    }
    if (!Array.isArray(rows)) {
      skipped.push(name);
      continue;
    }

    const columns = columnsOf(rows);
    // A column name is an identifier in `CREATE TABLE`, and the dump's keys are
    // untrusted: a key that is not a plain identifier is **renamed**, not skipped.
    // Skipping used to drop the whole table, which is how the frame section table
    // disappeared from every book (see `columnFor`).
    if (columns.length === 0) {
      // An empty table carries no information; record it and move on.
      tables.push({ name, rows: 0 });
      hashParts.push(`${name}:0:${statSync(file).size}`);
      continue;
    }

    const mapping = columnNames(columns);
    for (const { source, column } of mapping) {
      if (source !== column) renamed.push(`${name}.${source}→${column}`);
    }

    const columnDefs = mapping
      .map(({ source, column }) => `${quote(column)} ${columnType(rows.map((row) => row[source]))}`)
      .join(', ');

    db.exec('BEGIN');
    try {
      db.exec(`DROP TABLE IF EXISTS ${quote(name)}`);
      db.exec(`CREATE TABLE ${quote(name)} (${columnDefs})`);
      const placeholders = mapping.map(() => '?').join(', ');
      const insert = db.prepare(
        `INSERT INTO ${quote(name)} (${mapping.map((entry) => quote(entry.column)).join(', ')}) VALUES (${placeholders})`,
      );
      for (const row of rows) {
        insert.run(...mapping.map(({ source }) => {
          const value = row[source];
          if (value === undefined || value === null) return null;
          if (typeof value === 'boolean') return value ? 1 : 0;
          return value as string | number;
        }));
      }
      db.exec('COMMIT');
    } catch (error) {
      db.exec('ROLLBACK');
      throw error;
    }

    tables.push({ name, rows: rows.length });
    hashParts.push(`${name}:${rows.length}:${statSync(file).size}`);
  }

  const sourceHash = createHash('sha256').update(hashParts.sort().join('\n')).digest('hex');
  const importedAt = Date.now();

  const meta: Record<string, string> = {
    imported_at: String(importedAt),
    source_file: dir,
    source_hash: sourceHash,
    row_counts: JSON.stringify(Object.fromEntries(tables.map((t) => [t.name, t.rows]))),
    book_kind: readBookKind(dir),
  };
  const writeMeta = db.prepare(
    'INSERT INTO price_book_meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value',
  );
  for (const key of PRICE_META_KEYS) writeMeta.run(key, meta[key]);

  return { tables, importedAt, sourceFile: dir, sourceHash, skipped, renamed };
}
